        [[nodiscard]] static bool is_ws_only(std::string_view s) noexcept
        {
            for (unsigned char c : s)
                if (c > ' ') return false;
            return true;
        }

        [[nodiscard]] static std::string normalize_editor_text_for_gui(std::string_view text)
        {
            std::string out{};
            out.reserve(text.size());

            for (std::size_t i = 0; i < text.size(); ++i)
            {
                const auto ch = static_cast<unsigned char>(text[i]);
                if (ch == '\r')
                    continue;
                if (ch == '\n' || ch == '\t')
                {
                    out.push_back(static_cast<char>(ch));
                    continue;
                }
                if (ch >= 32u && ch < 127u)
                {
                    out.push_back(static_cast<char>(ch));
                    continue;
                }

                auto has = [&](std::initializer_list<unsigned char> bytes) noexcept {
                    if (i + bytes.size() > text.size())
                        return false;
                    std::size_t offset = 0;
                    for (const unsigned char expected : bytes)
                    {
                        if (static_cast<unsigned char>(text[i + offset]) != expected)
                            return false;
                        ++offset;
                    }
                    return true;
                };

                if (has({ 0xC2u, 0xA0u }))
                {
                    out.push_back(' ');
                    i += 1;
                }
                else if (has({ 0xE2u, 0x80u, 0x93u }) || has({ 0xE2u, 0x80u, 0x94u }) || has({ 0xE2u, 0x88u, 0x92u }))
                {
                    out.push_back('-');
                    i += 2;
                }
                else if (has({ 0xE2u, 0x80u, 0x98u }) || has({ 0xE2u, 0x80u, 0x99u }))
                {
                    out.push_back('\'');
                    i += 2;
                }
                else if (has({ 0xE2u, 0x80u, 0x9Cu }) || has({ 0xE2u, 0x80u, 0x9Du }))
                {
                    out.push_back('"');
                    i += 2;
                }
                else if (has({ 0xE2u, 0x80u, 0xA6u }))
                {
                    out += "...";
                    i += 2;
                }
                else if (has({ 0xE2u, 0x86u, 0x92u }))
                {
                    out += "->";
                    i += 2;
                }
                else
                {
                    out.push_back(' ');
                    while (i + 1 < text.size() && (static_cast<unsigned char>(text[i + 1]) & 0xC0u) == 0x80u)
                        ++i;
                }
            }

            return out;
        }

        struct AiChatRequestState
        {
            std::string reply{};
            std::string error{};
            std::atomic_bool cancelled{false};
            std::atomic_bool ready{false};
        };

        struct AiChat
        {
            static constexpr std::size_t kMaxLines = 200;
            std::vector<std::string> lines{};
            std::string input{};
            std::string pendingPrompt{};
            std::string latestRawReply{};
            std::uint64_t completionGeneration{};
            std::shared_ptr<AiChatRequestState> pending{};
            std::jthread worker{};

            AiChat()
            {
                lines.emplace_back("ai> Ready. Epoch will ask before using a discovered local model.");
                trim_lines();
            }

            AiChat(const AiChat&) = delete;
            AiChat& operator=(const AiChat&) = delete;
            AiChat(AiChat&&) noexcept = default;
            AiChat& operator=(AiChat&&) noexcept = default;

            void pump()
            {
                if (!pending
                    || !pending->ready.load(std::memory_order_acquire))
                    return;

                if (pending->cancelled.load(std::memory_order_acquire))
                {
                    if (worker.joinable())
                        worker.join();
                    ++completionGeneration;
                    latestRawReply.clear();
                    pendingPrompt.clear();
                    pending.reset();
                    return;
                }

                if (pending->error.empty())
                {
                    latestRawReply = std::move(pending->reply);
                    ++completionGeneration;
                    std::string reply =
                        normalize_editor_text_for_gui(latestRawReply);
                    if (reply.empty()) reply = "(empty reply)";
                    lines.emplace_back("ai> " + reply);
                    pendingPrompt.clear();
                    trim_lines();
                }
                else
                {
                    ++completionGeneration;
                    lines.emplace_back(
                        std::string("ai> (error) ") + pending->error);
                    latestRawReply.clear();
                    pendingPrompt.clear();
                    trim_lines();
                }

                if (worker.joinable())
                    worker.join();
                pending.reset();
            }

            [[nodiscard]] bool cancel_pending(bool cancelTransport = false)
            {
                if (!pending)
                    return false;
                pending->cancelled.store(true, std::memory_order_release);
                pendingPrompt.clear();
                if (cancelTransport)
                    epochengine::ai::cancel_engine_ai_request();
                return true;
            }

            void append_status(std::string text)
            {
                text = normalize_editor_text_for_gui(text);
                if (text.empty())
                    return;
                lines.emplace_back("ai> " + std::move(text));
                trim_lines();
            }

            void submit(std::string text)
            {
                (void)submit_with_display(std::move(text), {});
            }

            [[nodiscard]] bool submit_with_display(
                std::string text,
                std::string displayText,
                epochengine::ai::InferenceWorkload workload =
                    epochengine::ai::InferenceWorkload::chat)
            {
                if (text.empty() || is_ws_only(text))
                    return false;
                displayText = normalize_editor_text_for_gui(
                    displayText.empty() ? text : displayText);
                if (displayText.empty())
                    displayText = "(bounded local-model request)";

                if (pending)
                {
                    lines.emplace_back("ai> (busy)");
                    trim_lines();
                    return false;
                }

                lines.emplace_back("you> " + displayText);
                trim_lines();
                latestRawReply.clear();
                pendingPrompt = displayText;

                pending = std::make_shared<AiChatRequestState>();
                if (worker.joinable())
                    worker.join();
                worker = std::jthread(
                    [request = pending,
                     t = std::move(text),
                     workload]() mutable
                    {
                        try
                        {
                            epochengine::systems::threading::ScopedThreadActivity
                                threadActivity{};
                            request->reply =
                                epochengine::ai::send_to_engine_ai(t, workload);
                        }
                        catch (const std::exception& e)
                        {
                            request->error = e.what();
                        }
                        catch (...)
                        {
                            request->error =
                                "The local-model request failed with an unknown error.";
                        }
                        request->ready.store(
                            true, std::memory_order_release);
                    });
                return true;
            }
        private:
            void trim_lines()
            {
                if (lines.size() > kMaxLines)
                {
                    lines.erase(
                        lines.begin(),
                        lines.begin() + static_cast<std::ptrdiff_t>(lines.size() - kMaxLines));
                }
            }
        };

        [[nodiscard]] static std::string last_chat_line_with_prefix(const AiChat& chat, std::string_view prefix)
        {
            for (auto it = chat.lines.rbegin(); it != chat.lines.rend(); ++it)
            {
                if (it->rfind(prefix, 0) == 0)
                    return it->substr(prefix.size());
            }
            return {};
        }

